import {parseDocument} from '/ocr-rules.js';
let scanActive=false;
const score=r=>Object.keys(r.fields).length+(r.documentType!=='unknown'?2:0)+(r.status==='extracted'?3:0);
function paperBounds(context,w,h){const {data}=context.getImageData(0,0,w,h),step=Math.max(1,Math.floor(w/500));const rows=[];
 for(let y=0;y<h;y+=step){let dark=0,total=0;for(let x=0;x<w;x+=step){const p=(y*w+x)*4;total++;if((data[p]+data[p+1]+data[p+2])/3<215)dark++;}rows.push({y,hit:dark/total>.06});}
 let best=[0,h],start=-1,bestLength=0,gap=0;for(const {y,hit} of [...rows,{y:h,hit:false}]){if(hit){if(start<0)start=y;gap=0;}else if(start>=0){gap+=step;if(gap>h*.035||y===h){const end=y-gap;if(end-start>bestLength){best=[start,end];bestLength=end-start;}start=-1;}}}
 if(bestLength<h*.2)return {x:0,y:0,w,h};let minX=w,maxX=0;for(let x=0;x<w;x+=step){let n=0,t=0;for(let y=best[0];y<best[1];y+=step){const p=(y*w+x)*4;t++;if((data[p]+data[p+1]+data[p+2])/3<215)n++;}if(n/t>.08){minX=Math.min(minX,x);maxX=x;}}
 if(maxX-minX<w*.2)return {x:0,y:0,w,h};const pad=Math.round(Math.min(w,h)*.025);const x=Math.max(0,minX-pad),y=Math.max(0,best[0]-pad);return {x,y,w:Math.min(w-x,maxX-minX+2*pad),h:Math.min(h-y,best[1]-best[0]+2*pad)};
}
function prepare(source){const max=2500,scale=Math.min(1,max/Math.max(source.width,source.height));const canvas=document.createElement('canvas');canvas.width=Math.round(source.width*scale);canvas.height=Math.round(source.height*scale);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,canvas.width,canvas.height);const b=paperBounds(ctx,canvas.width,canvas.height);const out=document.createElement('canvas');out.width=b.w;out.height=b.h;const c=out.getContext('2d',{willReadFrequently:true});c.drawImage(canvas,b.x,b.y,b.w,b.h,0,0,b.w,b.h);const im=c.getImageData(0,0,b.w,b.h);for(let i=0;i<im.data.length;i+=4){const gray=.299*im.data[i]+.587*im.data[i+1]+.114*im.data[i+2];const value=Math.max(0,Math.min(255,(gray-128)*1.7+128));im.data[i]=im.data[i+1]=im.data[i+2]=value;}c.putImageData(im,0,0);return out;}
function bottom(source){const canvas=document.createElement('canvas');const y=Math.floor(source.height*.43);canvas.width=source.width;canvas.height=source.height-y;canvas.getContext('2d').drawImage(source,0,y,source.width,canvas.height,0,0,canvas.width,canvas.height);return canvas;}
async function* pages(file){if(file.type==='application/pdf'){const pdf=await import('/vendor/pdf.min.mjs');pdf.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.min.mjs';const task=pdf.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const doc=await task.promise;try{for(let i=1;i<=Math.min(doc.numPages,3);i++){const p=await doc.getPage(i),v=p.getViewport({scale:1});const view=p.getViewport({scale:Math.min(3,2300/Math.max(v.width,v.height))});const canvas=document.createElement('canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await p.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;yield {canvas,page:i,pageCount:doc.numPages};}}finally{await doc.destroy();}}else{const bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});try{yield {canvas:bitmap,page:1,pageCount:1}}finally{bitmap.close();}}}
export async function scanDocument(file,onProgress=()=>{}){
 if(scanActive)throw new Error('A document is already being scanned. Wait for it to finish.');scanActive=true;let worker,timer;
 try{onProgress('Loading OCR engine…');const {createWorker,PSM}=await import('/vendor/tesseract.esm.min.js');
 const operation=(async()=>{worker=await createWorker('eng',1,{workerPath:'/vendor/ocr-worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@7.0.0',logger:m=>onProgress(m.status==='recognizing text'?'Reading document… '+Math.round(m.progress*100)+'%':m.status)});await worker.setParameters({tessedit_pageseg_mode:PSM.AUTO});let best=null;
 for await(const item of pages(file)){const prepared=prepare(item.canvas);for(const [index,canvas] of [prepared,bottom(prepared)].entries()){onProgress('Scanning page '+item.page+(index?' · detail pass':''));const {data}=await worker.recognize(canvas,{}, {text:true});const result={...parseDocument(data.text,data.confidence),page:item.page,pageCount:item.pageCount};if(!best||score(result)>score(best))best=result;if(best.status==='extracted'&&best.fields[best.documentType+'Number'])break;}if(best?.status==='extracted')break;}
 if(!best)throw new Error('No readable page was found. Try a clear photograph or enter details manually.');if(best.pageCount>3)best.warnings.push('Only the first three PDF pages are scanned. Upload the identity page separately if needed.');return best;})();
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('OCR timed out. Check your connection, try a smaller clear image, or enter details manually.')),180000)});return await Promise.race([operation,timeout]);
 }finally{clearTimeout(timer);if(worker)await worker.terminate();scanActive=false;}
}
